        for (; (char *)dynp + (ptrdiff_t)sizeof(*dynp) <= end; ++dynp) {
            if (get_te64(&dynp->d_tag) == key) {
                return dynp;
            }
            if (Elf64_Dyn::DT_NULL == dynp->d_tag) {
                return nullptr;
            }
        }
    }
    return nullptr;
